"""Validated, versioned capability contracts generated by the platform builder."""
import json
from typing import Literal
from uuid import UUID

from jsonschema import Draft202012Validator
from pydantic import Field, field_validator, model_validator

from app.models.agents import StrictModel
from app.capabilities.worker import validate_code


SCHEMA_KEYS = {'type', 'properties', 'required', 'additionalProperties', 'items', 'enum',
               'minimum', 'maximum', 'minLength', 'maxLength', 'minItems', 'maxItems',
               'title', 'description', 'default'}


def check_schema(schema, depth=0):
    if depth > 12 or not isinstance(schema, dict) or set(schema) - SCHEMA_KEYS:
        raise ValueError('Schema 仅支持基础 JSON 类型、属性、数组和长度/数值约束，不支持引用或表达式。')
    if schema.get('type') not in {'object', 'array', 'string', 'number', 'integer', 'boolean', 'null'}:
        raise ValueError('每个 Schema 节点必须声明基础 type。')
    if 'additionalProperties' in schema and not isinstance(schema['additionalProperties'], bool):
        raise ValueError('additionalProperties 必须是布尔值。')
    for child in schema.get('properties', {}).values():
        check_schema(child, depth + 1)
    if 'items' in schema:
        check_schema(schema['items'], depth + 1)
    Draft202012Validator.check_schema(schema)
    return schema


class MethodTest(StrictModel):
    name: str = Field(min_length=1, max_length=100)
    arguments: dict
    expected: dict


class GeneratedMethod(StrictModel):
    name: str = Field(pattern=r'^[a-z][a-z0-9_]{0,47}$')
    description: str = Field(min_length=1, max_length=1200)
    input_schema: dict
    output_schema: dict
    code: str = Field(min_length=1, max_length=16000)
    tests: list[MethodTest] = Field(min_length=2, max_length=6)

    @field_validator('input_schema', 'output_schema')
    @classmethod
    def schema_is_safe(cls, value):
        if len(json.dumps(value)) > 20000 or value.get('type') != 'object':
            raise ValueError('输入与输出必须是对象，Schema 不能超过 20 KB。')
        try:
            return check_schema(value)
        except Exception as error:
            raise ValueError(f'Schema 无效：{str(error)[:200]}') from error

    @field_validator('code')
    @classmethod
    def code_is_supported(cls, value):
        try:
            validate_code(value)
        except (SyntaxError, ValueError) as error:
            raise ValueError(str(error)) from error
        return value

    @model_validator(mode='after')
    def tests_match_contract(self):
        for test in self.tests:
            try:
                Draft202012Validator(self.input_schema).validate(test.arguments)
                Draft202012Validator(self.output_schema).validate(test.expected)
                json.dumps(test.model_dump(), allow_nan=False)
            except Exception as error:
                raise ValueError(f'测试样例与接口约定不匹配：{str(error)[:200]}') from error
        return self


class BuildPlan(StrictModel):
    status: Literal['needs_input', 'ready']
    message: str = Field(min_length=1, max_length=4000)
    name: str = Field(default='', max_length=90)
    description: str = Field(default='', max_length=1200)
    system_prompt: str = Field(default='', max_length=12000)
    tools: list[GeneratedMethod] = Field(default_factory=list, max_length=6)

    @model_validator(mode='after')
    def complete_ready_plan(self):
        if self.status == 'ready' and not all([self.name, self.description, self.system_prompt, self.tools]):
            raise ValueError('可发布的方案需要名称、用途、指令和实际方法。')
        names = [tool.name for tool in self.tools]
        if len(names) != len(set(names)):
            raise ValueError('方法名称不能重复。')
        if len(self.model_dump_json().encode()) > 120000:
            raise ValueError('能力包超过 120 KB，请拆成更小的职责。')
        return self


class StartBuild(StrictModel):
    request_id: UUID
    message: str = Field(min_length=2, max_length=8000)
    base_package_id: str | None = Field(default=None, pattern=r'^pkg_[a-f0-9]{32}$')


class ReviseBuild(StrictModel):
    message: str = Field(min_length=1, max_length=8000)
    expected_revision: int = Field(ge=1)


class PublishBuild(StrictModel):
    expected_revision: int = Field(ge=1)
